import { MentionInput, type MentionSuggestion, type MentionInputValueDetail } from '@absoluteui/components/mention-input';

const people: MentionSuggestion[] = [
  { id: 'u1', label: 'Ana', description: 'People team' },
  { id: 'u2', label: 'Ben', description: 'Engineering' },
];
const tags: MentionSuggestion[] = [{ id: 't1', label: 'onboarding' }, { id: 't2', label: 'payroll' }];
const match = (list: MentionSuggestion[], query: string): MentionSuggestion[] => list.filter((s) => s.label.toLowerCase().startsWith(query.toLowerCase()));

const host = document.createElement('div');
document.body.append(host);
MentionInput.create(host, {
  label: 'Comment',
  maxLength: 500,
  showCounter: true,
  triggers: [
    { char: '@', label: '@ for people', provider: async (query) => match(people, query) },
    { char: '#', label: '# for tags', provider: async (query) => match(tags, query) },
  ],
});
host.addEventListener('aui-change', (event) => {
  const { value } = (event as CustomEvent<MentionInputValueDetail>).detail;
  console.log(value.text, value.mentions.map((m) => m.id));
});

import { MentionInput, type MentionSuggestion } from '@absoluteui/components/mention-input';

const host = document.createElement('div');
document.body.append(host);
MentionInput.create(host, {
  label: 'Note',
  debounce: 250,
  triggers: [
    {
      char: '@',
      minChars: 1,
      provider: async (query, { signal }) => {
        const response = await fetch(`/api/people?q=${encodeURIComponent(query)}`, { signal });
        return (await response.json()) as MentionSuggestion[];
      },
    },
  ],
});

